double adaptive_midpoint(FunctionPtr f, double a, double b, double precision) {
    double c = (a + b) / 2.0;
    double full_interval = (b - a) * f(c);
    double left_interval = (c - a) * f((a + c) / 2.0);
    double right_interval = (b - c) * f((c + b) / 2.0);
    double sum_halves = left_interval + right_halves;
    double error = std::abs(full_interval - sum_halves);

    if (error <= precision * std::abs(sum_halves)) {
        return sum_halves;
    } else {
        return adaptive_midpoint(f, a, c, precision / 2.0) + adaptive_midpoint(f, c, b, precision / 2.0);
    }
}

